import { escapeHtml, layout } from './layout.js';

function bookCard(book, showFinishButton) {
  const finishForm = showFinishButton
    ? `<form action="/books/${escapeHtml(book.id)}/finish" method="post" class="inline-form">
         <button type="submit" class="btn btn-small">Mark finished</button>
       </form>`
    : '';

  return `<li class="book-card">
    <a href="/books/${escapeHtml(book.id)}" class="book-link">
      <span class="book-title">${escapeHtml(book.title)}</span>
      <span class="book-author">${escapeHtml(book.author)}</span>
    </a>
    ${finishForm}
  </li>`;
}

export function renderHome(reading, finished) {
  const readingList =
    reading.length > 0
      ? `<ul class="book-list">${reading.map((b) => bookCard(b, true)).join('')}</ul>`
      : '<p class="empty">Nothing on the go right now.</p>';

  const finishedList =
    finished.length > 0
      ? `<ul class="book-list">${finished.map((b) => bookCard(b, false)).join('')}</ul>`
      : '<p class="empty">No finished books yet.</p>';

  const body = `
    <section class="add-book">
      <h1>Add a book</h1>
      <form action="/books" method="post" class="book-form">
        <label>
          Title
          <input type="text" name="title" required placeholder="The Left Hand of Darkness">
        </label>
        <label>
          Author
          <input type="text" name="author" required placeholder="Ursula K. Le Guin">
        </label>
        <label>
          Notes <span class="optional">(optional)</span>
          <textarea name="notes" rows="3" placeholder="Thoughts, quotes, why you picked it up…"></textarea>
        </label>
        <button type="submit" class="btn">Add book</button>
      </form>
    </section>

    <section>
      <h2>Currently reading</h2>
      ${readingList}
    </section>

    <section>
      <h2>Finished</h2>
      ${finishedList}
    </section>`;

  return layout('Home', body);
}

