import { escapeHtml, layout } from './layout.js';

export function renderBook(book) {
  const notes = book.notes
    ? `<div class="notes"><p>${escapeHtml(book.notes).replace(/\n/g, '<br>')}</p></div>`
    : '<p class="empty">No notes yet.</p>';

  const finishAction =
    book.status === 'reading'
      ? `<form action="/books/${escapeHtml(book.id)}/finish" method="post">
           <button type="submit" class="btn">Mark as finished</button>
         </form>`
      : `<p class="status-badge finished">Finished</p>`;

  const body = `
    <article class="book-detail">
      <a href="/" class="back-link">← Back to list</a>
      <h1>${escapeHtml(book.title)}</h1>
      <p class="book-author-large">by ${escapeHtml(book.author)}</p>
      ${finishAction}
      <section class="notes-section">
        <h2>Notes</h2>
        ${notes}
      </section>
      <p class="share-hint">Share this page: <code>${escapeHtml(`/books/${book.id}`)}</code></p>
    </article>`;

  return layout(book.title, body);
}

export function renderNotFound() {
  const body = `
    <div class="not-found">
      <h1>Book not found</h1>
      <p>That link doesn't match any book in your list.</p>
      <a href="/" class="btn">Go home</a>
    </div>`;

  return layout('Not found', body);
}

