  font-family: Georgia, 'Times New Roman', serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
}

.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  padding: 1rem 1.5rem;
}

.logo {
  font-size: 1.125rem;
  font-weight: normal;
  color: var(--accent);
  text-decoration: none;
  letter-spacing: 0.02em;
}

.container {
  max-width: 640px;
  margin: 0 auto;
  padding: 2rem 1.5rem 4rem;
}

h1 {
  font-size: 1.75rem;
  font-weight: normal;
  margin: 0 0 1rem;
}

h2 {
  font-size: 1.125rem;
  font-weight: normal;
  color: var(--muted);
  margin: 2.5rem 0 1rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 0.8rem;
}

section.add-book {
  margin-bottom: 1rem;
}

.book-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  background: var(--surface);
  padding: 1.5rem;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
}

.book-form label {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  font-size: 0.9rem;
}

.optional {
  color: var(--muted);
  font-weight: normal;
}

input,
textarea {
  font: inherit;
  font-family: system-ui, -apple-system, sans-serif;
  padding: 0.6rem 0.75rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg);
}

input:focus,
textarea:focus {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.btn {
  display: inline-block;
  font: inherit;
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 0.9rem;
  padding: 0.6rem 1.25rem;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  text-decoration: none;
  width: fit-content;
}

.btn:hover {
  background: var(--accent-hover);
}

.btn-small {
  padding: 0.35rem 0.75rem;
  font-size: 0.8rem;
}

.book-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.book-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.75rem 1rem;
  box-shadow: var(--shadow);
}

.book-link {
  text-decoration: none;
  color: inherit;
  flex: 1;
  min-width: 0;
}

.book-link:hover .book-title {
  color: var(--accent);
}

.book-title {
  display: block;
  font-size: 1.05rem;
}

.book-author {
  display: block;
  font-size: 0.9rem;
  color: var(--muted);
}

.inline-form {
  flex-shrink: 0;
}

.empty {
  color: var(--muted);
  font-style: italic;
  margin: 0;
}

.back-link {
  display: inline-block;
  color: var(--muted);
  text-decoration: none;
  font-size: 0.9rem;
  margin-bottom: 1.5rem;
}

.back-link:hover {
  color: var(--accent);
}

.book-detail h1 {
  font-size: 2rem;
  margin-bottom: 0.25rem;
}

.book-author-large {
  font-size: 1.1rem;
  color: var(--muted);
  margin: 0 0 1.5rem;
}

.status-badge {
  display: inline-block;
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 0.35rem 0.75rem;
  border-radius: var(--radius);
  margin: 0 0 2rem;
}

.status-badge.finished {
  background: #e8f0ec;
  color: var(--accent);
}

.notes-section {
  margin-top: 2rem;
}

.notes {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.25rem 1.5rem;
  box-shadow: var(--shadow);
}

.notes p {
  margin: 0;
  white-space: pre-wrap;
}

.share-hint {
  margin-top: 2.5rem;
  font-size: 0.85rem;
  color: var(--muted);
}

.share-hint code {
  font-family: ui-monospace, monospace;
  font-size: 0.8rem;
  background: var(--surface);
  padding: 0.2rem 0.4rem;
  border-radius: 4px;
  border: 1px solid var(--border);
}

.not-found {
  text-align: center;
  padding: 3rem 0;
}

.not-found h1 {
  margin-bottom: 0.5rem;
}

.not-found p {
  color: var(--muted);
  margin-bottom: 1.5rem;
}

