import express from 'express';
import { randomUUID } from 'node:crypto';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { readBooks, writeBooks, getBook } from './lib/store.js';
import { renderHome } from './views/home.js';
import { renderBook, renderNotFound } from './views/book.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();
const PORT = process.env.PORT || 3000;

app.use(express.urlencoded({ extended: true }));
app.use(express.static(path.join(__dirname, 'public')));

app.get('/', async (_req, res) => {
  const books = await readBooks();
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books.filter((b) => b.status === 'finished');
  res.send(renderHome(reading, finished));
});

app.post('/books', async (req, res) => {
  const title = (req.body.title || '').trim();
  const author = (req.body.author || '').trim();
  const notes = (req.body.notes || '').trim();

  if (!title || !author) {
    return res.redirect('/');
  }

  const books = await readBooks();
  books.push({
    id: randomUUID(),
    title,
    author,
    notes,
    status: 'reading',
    createdAt: new Date().toISOString(),
    finishedAt: null,
  });
  await writeBooks(books);
  res.redirect('/');
});

app.get('/books/:id', async (req, res) => {
  const book = await getBook(req.params.id);
  if (!book) {
    return res.status(404).send(renderNotFound());
  }
  res.send(renderBook(book));
});

app.post('/books/:id/finish', async (req, res) => {
  const books = await readBooks();
  const book = books.find((b) => b.id === req.params.id);
  if (book && book.status === 'reading') {
    book.status = 'finished';
    book.finishedAt = new Date().toISOString();
    await writeBooks(books);
  }
  const referer = req.get('Referer');
  res.redirect(referer && referer.includes(`/books/${book?.id}`) ? referer : '/');
});

app.listen(PORT, () => {
  console.log(`Reading list running at http://localhost:${PORT}`);
});

